import java.util.*;

import jakarta.validation.*;
import jakarta.validation.constraints.*;

public class Main {
    static final Validator VALIDATOR = Validation.buildDefaultValidatorFactory().getValidator();

    static void periksa(Object o) {
        List<String> pesan = new ArrayList<>();
        for (ConstraintViolation<Object> v : VALIDATOR.validate(o)) {
            pesan.add(v.getPropertyPath() + ": " + v.getMessage());
        }
        Collections.sort(pesan);
        if (pesan.isEmpty()) {
            System.out.println("Valid");
        }
        for (String p : pesan) {
            System.out.println(p);
        }
    }

    public static void main(String[] args) {
        periksa(new TodoBaru("ab"));
    }
}

class TodoBaru {
    @Size(min = 3, max = 50, message = "Judul {min} sampai {max} huruf")
    String judul;

    TodoBaru(String judul) {
        this.judul = judul;
    }
}

